"use client"

import { createContext, type ReactNode, useContext, useId } from "react"
import { NumberField as NumberFieldPrimitive } from "@base-ui/react/number-field"
import { cva, type VariantProps } from "class-variance-authority"

import { cn } from "@/lib/utils"
import { Label } from "@/components/ui/label"

import "@/styles/text-control.styles.css"
import "@/styles/number-field.styles.css"

//Icons
import { MinusIcon, PlusIcon } from "lucide-react"

const NumberFieldContext = createContext<{
  fieldId: string
  size: "sm" | "default" | "lg"
} | null>(null)

const numberFieldGroupVariants = cva("input-control-layout number-group-layout", {
  variants: { size: { sm: "number-sm-layout", default: "", lg: "number-lg-layout" } },
  defaultVariants: { size: "default" },
})
const numberFieldButtonVariants = cva("number-stepper-layout", {
  variants: {
    size: { sm: "number-stepper-sm-layout", default: "", lg: "number-stepper-lg-layout" },
  },
  defaultVariants: { size: "default" },
})
const numberFieldInputVariants = cva("input-layout number-input-layout", {
  variants: { size: { sm: "number-input-sm-layout", default: "", lg: "number-input-lg-layout" } },
  defaultVariants: { size: "default" },
})

function NumberField({
  id,
  className,
  size = "default",
  ...props
}: NumberFieldPrimitive.Root.Props & VariantProps<typeof numberFieldGroupVariants>) {
  const generatedId = useId()
  const fieldId = id ?? generatedId
  const sizeValue = size ?? "default"

  return (
    <NumberFieldContext.Provider value={{ fieldId, size: sizeValue }}>
      <NumberFieldPrimitive.Root
        className={cn("number-field-layout", className)}
        data-size={sizeValue}
        data-slot="number-field"
        id={fieldId}
        {...props}
      />
    </NumberFieldContext.Provider>
  )
}

function NumberFieldGroup({
  className,
  size: sizeProp,
  ...props
}: NumberFieldPrimitive.Group.Props & Partial<VariantProps<typeof numberFieldGroupVariants>>) {
  const context = useContext(NumberFieldContext)
  if (!context) {
    throw new Error("NumberFieldGroup must be used within a NumberField component.")
  }
  const size = sizeProp ?? context.size

  return (
    <NumberFieldPrimitive.Group
      className={cn(numberFieldGroupVariants({ size }), className)}
      data-slot="number-field-group"
      {...props}
    />
  )
}

function NumberFieldDecrement({
  className,
  size: sizeProp,
  children,
  ...props
}: NumberFieldPrimitive.Decrement.Props &
  Partial<VariantProps<typeof numberFieldButtonVariants>> & {
    children?: React.ReactNode
  }) {
  const context = useContext(NumberFieldContext)
  if (!context) {
    throw new Error("NumberFieldDecrement must be used within a NumberField component.")
  }
  const size = sizeProp ?? context.size

  return (
    <NumberFieldPrimitive.Decrement
      className={cn(numberFieldButtonVariants({ size }), "number-decrement-layout", className)}
      data-slot="number-field-decrement"
      tabIndex={0}
      {...props}
    >
      {children ?? <MinusIcon aria-hidden="true" />}
    </NumberFieldPrimitive.Decrement>
  )
}

function NumberFieldIncrement({
  className,
  size: sizeProp,
  children,
  ...props
}: NumberFieldPrimitive.Increment.Props &
  Partial<VariantProps<typeof numberFieldButtonVariants>> & {
    children?: ReactNode
  }) {
  const context = useContext(NumberFieldContext)
  if (!context) {
    throw new Error("NumberFieldIncrement must be used within a NumberField component.")
  }
  const size = sizeProp ?? context.size

  return (
    <NumberFieldPrimitive.Increment
      className={cn(numberFieldButtonVariants({ size }), "number-increment-layout", className)}
      data-slot="number-field-increment"
      tabIndex={0}
      {...props}
    >
      {children ?? <PlusIcon aria-hidden="true" />}
    </NumberFieldPrimitive.Increment>
  )
}

function NumberFieldInput({
  className,
  size: sizeProp,
  ...props
}: NumberFieldPrimitive.Input.Props & Partial<VariantProps<typeof numberFieldInputVariants>>) {
  const context = useContext(NumberFieldContext)
  if (!context) {
    throw new Error("NumberFieldInput must be used within a NumberField component.")
  }
  const size = sizeProp ?? context.size

  return (
    <NumberFieldPrimitive.Input
      className={cn(numberFieldInputVariants({ size }), className)}
      data-slot="number-field-input"
      {...props}
    />
  )
}

function NumberFieldScrubArea({
  className,
  label,
  ...props
}: NumberFieldPrimitive.ScrubArea.Props & {
  label: string
}) {
  const context = useContext(NumberFieldContext)
  if (!context) {
    throw new Error(
      "NumberFieldScrubArea must be used within a NumberField component for accessibility."
    )
  }

  return (
    <NumberFieldPrimitive.ScrubArea
      className={cn("number-scrub-layout", className)}
      data-slot="number-field-scrub-area"
      {...props}
    >
      <Label className="cursor-ew-resize" htmlFor={context.fieldId}>
        {label}
      </Label>
      <NumberFieldPrimitive.ScrubAreaCursor className="drop-shadow-[0_1px_1px_#0008] filter">
        <CursorGrowIcon />
      </NumberFieldPrimitive.ScrubAreaCursor>
    </NumberFieldPrimitive.ScrubArea>
  )
}

function CursorGrowIcon(props: React.ComponentProps<"svg">) {
  return (
    <svg
      fill="black"
      height="14"
      stroke="white"
      viewBox="0 0 24 14"
      width="26"
      xmlns="http://www.w3.org/2000/svg"
      {...props}
    >
      <path d="M19.5 5.5L6.49737 5.51844V2L1 6.9999L6.5 12L6.49737 8.5L19.5 8.5V12L25 6.9999L19.5 2V5.5Z" />
    </svg>
  )
}

export {
  NumberField,
  NumberFieldScrubArea,
  NumberFieldDecrement,
  NumberFieldIncrement,
  NumberFieldGroup,
  NumberFieldInput,
}

@layer components {
  .number-field-layout {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    width: 100%;
    min-width: 0;
    gap: calc(6 * var(--component-unit, 0.0625rem));
  }
  /* Unlike text-only shells, steppers may be disabled at a boundary while the input stays enabled. */
  .number-group-layout {
    align-items: center;
    border: 1px solid var(--input);
    background: var(--card);
    transition:
      border-color 100ms cubic-bezier(0.2, 0, 0, 1),
      background-color 100ms cubic-bezier(0.2, 0, 0, 1);
  }
  .number-group-layout:has(input:read-only) {
    background: var(--muted);
  }
  .number-group-layout:is([data-invalid], :has(input[aria-invalid="true"])):not([data-disabled]) {
    border-color: var(--destructive);
  }
  .number-group-layout:has(input:focus-visible) {
    outline: 2px solid var(--ring);
    outline-offset: 2px;
  }
  .number-group-layout[data-disabled] {
    background: var(--muted);
    border-color: var(--border);
    color: var(--muted-foreground);
  }
  .number-group-layout.number-sm-layout {
    --control-height: 32;
    --control-inset: 10;
    --control-type: 13;
    --control-leading: 18;
  }
  .number-group-layout.number-lg-layout {
    --control-height: 40;
    --control-inset: 14;
  }
  .number-input-layout {
    flex: 1;
    text-align: center;
    font-variant-numeric: tabular-nums;
  }
  .number-stepper-layout {
    position: relative;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    align-self: stretch;
    flex-shrink: 0;
    width: calc(var(--control-height) * var(--component-unit, 0.0625rem) - 2px);
    padding: 0;
    border: 0;
    border-radius: max(0px, calc(var(--control-radius, var(--radius)) - 1px));
    background: transparent;
    color: var(--foreground);
    cursor: pointer;
    transition: background-color 100ms cubic-bezier(0.2, 0, 0, 1);
  }
  .number-stepper-layout svg {
    width: calc(16 * var(--component-unit, 0.0625rem));
    height: calc(16 * var(--component-unit, 0.0625rem));
    pointer-events: none;
  }
  .number-stepper-layout:not(:disabled, [data-disabled], [data-readonly]):active {
    background: var(--secondary);
  }
  .number-stepper-layout:is(:disabled, [data-disabled], [data-readonly]) {
    color: var(--muted-foreground);
    cursor: not-allowed;
  }
  .number-group-layout[data-readonly] .number-stepper-layout {
    cursor: default;
  }
  .number-stepper-layout:focus-visible {
    outline: 2px solid var(--ring);
    outline-offset: -3px;
    z-index: 1;
  }
  .number-scrub-layout {
    display: flex;
    cursor: ew-resize;
  }
  .number-scrub-layout:is([data-disabled], [data-readonly]) label {
    cursor: default;
  }
}
@media (hover: hover) {
  @layer components {
    .number-group-layout:not(
        [data-disabled],
        [data-invalid],
        :has(input[aria-invalid="true"])
      ):hover {
      border-color: color-mix(in oklab, var(--input) 75%, var(--foreground));
    }
    .number-stepper-layout:not(:disabled, [data-disabled], [data-readonly], :active):hover {
      background: var(--muted);
    }
  }
}
@media (pointer: coarse) {
  @layer components {
    /* Border + 44px independent actions, with no invisible extensions. */
    .number-group-layout {
      min-height: calc(46 * var(--component-unit, 0.0625rem));
    }
    .number-group-layout:has(> div > .number-increment-layout + .number-decrement-layout) {
      min-height: calc(94 * var(--component-unit, 0.0625rem));
    }
    .number-stepper-layout {
      min-width: calc(44 * var(--component-unit, 0.0625rem));
      min-height: calc(44 * var(--component-unit, 0.0625rem));
    }
  }
}
@media (prefers-reduced-motion: reduce) {
  .number-stepper-layout,
  .number-group-layout {
    transition: none;
  }
}
@media (forced-colors: active) {
  .number-stepper-layout:focus-visible,
  .number-group-layout:has(input:focus-visible) {
    outline-color: Highlight;
  }
}
@layer components {
  .number-stepper-sm-layout {
    width: calc(30 * var(--component-unit, 0.0625rem));
  }
  .number-stepper-lg-layout {
    width: calc(38 * var(--component-unit, 0.0625rem));
  }
  .number-input-sm-layout {
    --control-inset: 10;
    font-size: calc(13 * var(--component-unit, 0.0625rem));
    line-height: calc(18 * var(--component-unit, 0.0625rem));
  }
  .number-input-lg-layout {
    --control-inset: 14;
    font-size: calc(14 * var(--component-unit, 0.0625rem));
    line-height: calc(20 * var(--component-unit, 0.0625rem));
  }
}

/* A disabled NumberField also owns the foreground of its composed Label. */
:where(.number-field-layout[data-disabled] label) {
  color: var(--muted-foreground);
}

/* Local text-entry anatomy, shared by Input, Textarea and InputGroup. */
@layer components {
  .input-control-layout,
  .textarea-control-layout,
  .input-group-layout {
    --control-height: 36;
    --control-inset: 12;
    --control-type: 14;
    --control-leading: 20;
    --textarea-min: 96;
    --textarea-block: 10;
    position: relative;
    display: inline-flex;
    box-sizing: border-box;
    width: 100%;
    min-width: 0;
    border-radius: var(--control-radius, var(--radius));
    font-size: calc(var(--control-type) * var(--component-unit, 0.0625rem));
    line-height: calc(var(--control-leading) * var(--component-unit, 0.0625rem));
  }
  .input-control-layout[data-size="sm"],
  .input-group-layout:has(
    .input-control-layout[data-size="sm"],
    .textarea-control-layout[data-size="sm"]
  ) {
    --control-height: 32;
    --control-inset: 10;
    --control-type: 13;
    --control-leading: 18;
    --textarea-min: 80;
    --textarea-block: 8;
  }
  .textarea-control-layout[data-size="sm"] {
    --control-inset: 10;
    --textarea-min: 80;
    --textarea-block: 8;
  }
  .input-control-layout[data-size="lg"],
  .textarea-control-layout[data-size="lg"],
  .input-group-layout:has(
    .input-control-layout[data-size="lg"],
    .textarea-control-layout[data-size="lg"]
  ) {
    --control-height: 40;
    --control-inset: 14;
    --textarea-min: 112;
    --textarea-block: 12;
  }
  .input-control-layout {
    height: calc(var(--control-height) * var(--component-unit, 0.0625rem));
  }
  .control-shell-layout,
  .input-group-layout {
    transition:
      border-color 100ms cubic-bezier(0.2, 0, 0, 1),
      background-color 100ms cubic-bezier(0.2, 0, 0, 1);
  }
  .control-shell-layout:has(input:focus-visible, textarea:focus-visible),
  .input-group-layout:has(input:focus-visible, textarea:focus-visible) {
    outline: 2px solid var(--ring);
    outline-offset: 2px;
  }
  .input-layout,
  .textarea-layout {
    box-sizing: border-box;
    width: 100%;
    min-width: 0;
    border: 0;
    border-radius: inherit;
    background: transparent;
    color: inherit;
    font: inherit;
    outline: none;
    padding-inline: calc(var(--control-inset) * var(--component-unit, 0.0625rem) - 1px);
  }
  .input-layout {
    height: 100%;
    padding-block: 0;
  }
  .input-layout::placeholder,
  .textarea-layout::placeholder {
    color: var(--muted-foreground);
    opacity: 1;
  }
  .input-layout:disabled,
  .textarea-layout:disabled {
    cursor: not-allowed;
  }
  .input-layout:disabled::placeholder,
  .textarea-layout:disabled::placeholder {
    color: var(--muted-foreground);
  }
  .textarea-control-layout {
    min-height: calc(var(--textarea-min) * var(--component-unit, 0.0625rem));
  }
  .textarea-layout {
    field-sizing: content;
    min-height: calc(var(--textarea-min) * var(--component-unit, 0.0625rem) - 2px);
    padding-block: calc(var(--textarea-block) * var(--component-unit, 0.0625rem) - 1px);
    resize: vertical;
  }
  .input-layout[type="search"]::-webkit-search-cancel-button,
  .input-layout[type="search"]::-webkit-search-decoration {
    appearance: none;
  }
  .input-layout[type="file"] {
    color: var(--muted-foreground);
  }
  .input-layout::file-selector-button {
    margin-inline-end: calc(12 * var(--component-unit, 0.0625rem));
    background: transparent;
    color: var(--foreground);
    font-weight: 500;
  }
  .input-group-layout {
    align-items: center;
    min-height: calc(var(--control-height) * var(--component-unit, 0.0625rem));
  }
  .input-group-layout > :is(.input-control-layout, .textarea-control-layout) {
    flex: 1;
    min-width: 0;
    border: 0;
    border-radius: inherit;
    background: transparent;
    outline: none;
  }
  .input-group-layout > .input-control-layout {
    height: calc(var(--control-height) * var(--component-unit, 0.0625rem) - 2px);
  }
  .input-group-layout .textarea-layout {
    resize: none;
  }
  .input-group-layout > .textarea-control-layout {
    min-height: calc(var(--textarea-min) * var(--component-unit, 0.0625rem) - 2px);
  }
  .input-group-layout:has([data-align="block-start"], [data-align="block-end"]) {
    flex-direction: column;
    align-items: stretch;
  }
  .input-group-layout:has([data-align="inline-start"]) .input-layout {
    padding-inline-start: calc(6 * var(--component-unit, 0.0625rem));
  }
  .input-group-layout:has([data-align="inline-end"]) .input-layout {
    padding-inline-end: calc(6 * var(--component-unit, 0.0625rem));
  }
  .input-group-addon-layout {
    display: flex;
    flex-shrink: 0;
    align-items: center;
    justify-content: center;
    gap: calc(6 * var(--component-unit, 0.0625rem));
    cursor: text;
    user-select: none;
    color: var(--muted-foreground);
  }
  .input-group-addon-layout[data-align="inline-start"] {
    order: -1;
    padding-inline-start: calc(var(--control-inset) * var(--component-unit, 0.0625rem) - 1px);
  }
  .input-group-addon-layout[data-align="inline-end"] {
    order: 1;
    padding-inline-end: calc(var(--control-inset) * var(--component-unit, 0.0625rem) - 1px);
  }
  .input-group-addon-layout[data-align="block-start"],
  .input-group-addon-layout[data-align="block-end"] {
    width: 100%;
    justify-content: flex-start;
    padding: calc(8 * var(--component-unit, 0.0625rem))
      calc(var(--control-inset) * var(--component-unit, 0.0625rem) - 1px);
  }
  .input-group-addon-layout[data-align="block-start"] {
    order: -1;
  }
  .input-group-addon-layout[data-align="block-end"] {
    order: 1;
  }
  .input-group-addon-layout :where(svg:not([class*="size-"])),
  .input-group-text-layout :where(svg:not([class*="size-"])) {
    width: calc(16 * var(--component-unit, 0.0625rem));
    height: calc(16 * var(--component-unit, 0.0625rem));
    flex-shrink: 0;
  }
  .input-group-text-layout {
    display: flex;
    align-items: center;
    gap: calc(6 * var(--component-unit, 0.0625rem));
    white-space: nowrap;
    color: var(--muted-foreground);
  }
  /* Actions consume their actual box, including focus clearance, without negative margins. */
  .input-group-layout :is(.button-layout, button, [role="button"]) {
    flex-shrink: 0;
  }
  .input-group-layout > .button-layout {
    margin: calc(3 * var(--component-unit, 0.0625rem));
  }
  .input-group-addon-layout:has(button, a, [role="button"]) {
    padding: calc(3 * var(--component-unit, 0.0625rem));
  }
  /* Explicit legacy geometry adapter for the protected Date/Time input shells. */
  :is(.rdp-input_surface, .tp-input_surface).input-control-layout {
    height: calc(2.25rem + 2px);
    border-radius: var(--radius);
    font-size: 1.1rem;
    line-height: 1.875rem;
  }
  :is(.rdp-input_surface, .tp-input_surface).input-control-layout[data-size="sm"] {
    height: calc(2rem + 2px);
  }
  :is(.rdp-input_surface, .tp-input_surface).input-control-layout[data-size="lg"] {
    height: calc(2.5rem + 2px);
  }
}
@media (min-width: 40rem) {
  @layer components {
    :is(.rdp-input_surface, .tp-input_surface).input-control-layout {
      font-size: 0.98rem;
    }
    :is(.rdp-input_surface, .tp-input_surface).input-control-layout[data-size="lg"] {
      height: calc(2.125rem + 2px);
    }
  }
}
@media (max-width: 40rem), (pointer: coarse) {
  @layer components {
    .input-layout:not(:read-only),
    .textarea-layout:not(:read-only) {
      font-size: calc(16 * var(--component-unit, 0.0625rem));
      line-height: calc(24 * var(--component-unit, 0.0625rem));
    }
  }
}
@media (prefers-reduced-motion: reduce) {
  .control-shell-layout,
  .input-group-layout {
    transition: none;
  }
}
@media (forced-colors: active) {
  .control-shell-layout:has(:focus-visible),
  .input-group-layout:has(input:focus-visible, textarea:focus-visible) {
    outline-color: Highlight;
  }
}
/* Composite value/state ownership; keep these selectors next to the layout they govern. */
.control-shell-layout:has(:read-only),
.input-group-layout:has(input:read-only, textarea:read-only) {
  background: var(--muted);
}
.control-shell-layout:has([aria-invalid="true"], [data-invalid]),
.input-group-layout:has(
  input[aria-invalid="true"],
  textarea[aria-invalid="true"],
  input[data-invalid],
  textarea[data-invalid]
) {
  border-color: var(--destructive);
}
.control-shell-layout:has(:disabled, [data-disabled]),
.input-group-layout:has(input:disabled, textarea:disabled) {
  color: var(--muted-foreground);
  background: var(--muted);
  border-color: var(--border);
}
@media (hover: hover) {
  .control-shell-layout:not(
      :has(:disabled, [data-disabled], [aria-invalid="true"], [data-invalid])
    ):hover,
  .input-group-layout:not(
      :has(input:disabled, textarea:disabled, [aria-invalid="true"], [data-invalid])
    ):hover {
    border-color: color-mix(in oklab, var(--input) 75%, var(--foreground));
  }
}
